sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var recordId = request.pathParams.record_id;
    var body = request.body.data || {};
    var message = body.message;

    var requestDebugInfo = {
        "url_endpoint": request.url,
        "http_method": request.queryString ? "GET/PARAMS" : "POST/PUT",
        "path_parameters": request.pathParams,
        "query_parameters": request.queryParams,
        "headers": request.headers,
        "raw_body_string": request.body.dataString, // Complete raw input payload
        "parsed_body_json": body
    };

    // This logs everything into System Logs > App Logs
    gs.info('AIVA Request Debug Log:\n' + JSON.stringify(requestDebugInfo, null, 4));

    if (!message) {
        response.setStatus(400);
        return {
            error: 'message is required'
        };
    }


    var aiva = new AIVAGenAIAssistant();
    // body.model is captured here for when you wire up multi-model routing
    // (see README) — processChat doesn't use it yet.
    var reply = aiva.processChat(recordId, message);

    if (reply && (reply.indexOf('Error:') === 0 || reply.indexOf('Exception:') === 0)) {
        response.setStatus(502);
        return {
            error: reply
        };
    }

    response.setStatus(200);
    return {
        recordId: recordId,
        reply: reply
    };
})(request, response);
